--
-- 表的结构 `nteam_academic_push_config`
--

CREATE TABLE `nteam_academic_push_config` (
  `id` int(11) NOT NULL DEFAULT '1',
  `schedule_reminder_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用课程提醒功能',
  `grade_notify_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用成绩通知功能',
  `wechat_push_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用微信推送',
  `email_push_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用邮件推送',
  `schedule_reminder_time` time DEFAULT '20:00:00' COMMENT '默认课程提醒时间',
  `quiet_hours_start` time DEFAULT '22:00:00' COMMENT '服务停止开始时间',
  `quiet_hours_end` time DEFAULT '08:00:00' COMMENT '服务停止结束时间',
  `grade_semester` varchar(50) DEFAULT '' COMMENT '成绩推送学期（空则自动获取当前学期）',
  `schedule_template_id` int(11) DEFAULT NULL COMMENT '课程提醒模板ID',
  `grade_template_id` int(11) DEFAULT NULL COMMENT '成绩通知模板ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学术推送全局配置表';

--
-- 转存表中的数据 `nteam_academic_push_config`
--

INSERT INTO `nteam_academic_push_config` (`id`, `schedule_reminder_enabled`, `grade_notify_enabled`, `wechat_push_enabled`, `email_push_enabled`, `schedule_reminder_time`, `quiet_hours_start`, `quiet_hours_end`, `grade_semester`, `schedule_template_id`, `grade_template_id`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 1, 1, '20:00:00', '22:00:00', '08:00:00', '2025-2026-1', 6, 3, '2026-05-04 08:13:07', '2026-05-04 11:49:19');

