--
-- 表的结构 `nteam_announcements`
--

CREATE TABLE `nteam_announcements` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL COMMENT '公告标题',
  `content` text NOT NULL COMMENT '公告内容(Markdown)',
  `thumbnail` varchar(500) DEFAULT NULL COMMENT '缩略图路径',
  `image` varchar(500) DEFAULT NULL COMMENT '大图路径',
  `is_top` tinyint(1) DEFAULT '0' COMMENT '是否置顶',
  `is_published` tinyint(1) DEFAULT '1' COMMENT '是否发布',
  `view_count` int(11) DEFAULT '0' COMMENT '浏览次数',
  `author` varchar(100) DEFAULT NULL COMMENT '作者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公告表';

