--
-- 表的结构 `nteam_mail_log`
--

CREATE TABLE `nteam_mail_log` (
  `id` int(11) NOT NULL,
  `to_email` varchar(255) NOT NULL COMMENT '接收邮箱',
  `subject` varchar(500) NOT NULL COMMENT '邮件主题',
  `content` text COMMENT '邮件内容摘要',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:0失败,1成功',
  `error_msg` text COMMENT '错误信息',
  `ip` varchar(50) DEFAULT NULL COMMENT '发送IP',
  `create_time` datetime NOT NULL COMMENT '发送时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邮件发送日志表';

-- --------------------------------------------------------

--
-- 表的结构 `nteam_power_config`
--

CREATE TABLE `nteam_power_config` (
  `id` int(11) NOT NULL,
  `power_fee_template_id` int(11) DEFAULT NULL COMMENT '电费提醒模板ID',
  `power_report_template_id` int(11) DEFAULT NULL COMMENT '电费报告模板ID',
  `price_per_kwh` decimal(10,4) DEFAULT '0.6100' COMMENT '每度电价格',
  `low_balance_threshold` decimal(10,2) DEFAULT '30.00' COMMENT '低余额阈值（全局默认）',
  `critical_balance_threshold` decimal(10,2) DEFAULT '10.00' COMMENT '临界余额阈值（全局默认）',
  `arrears_threshold` decimal(10,2) DEFAULT '0.00' COMMENT '欠费阈值',
  `daily_summary_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用每日用电汇总',
  `low_balance_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用余额不足提醒',
  `critical_balance_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用余额即将耗尽提醒',
  `arrears_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用欠费提醒',
  `email_push_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用邮件推送',
  `wechat_push_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用微信推送',
  `daily_summary_frequency` varchar(20) DEFAULT 'daily' COMMENT '每日汇总推送频率',
  `low_balance_frequency` varchar(20) DEFAULT 'daily' COMMENT '余额不足提醒频率',
  `critical_balance_frequency` varchar(20) DEFAULT 'always' COMMENT '余额即将耗尽提醒频率',
  `arrears_frequency` varchar(20) DEFAULT 'always' COMMENT '欠费提醒频率',
  `threshold_amount` decimal(10,2) DEFAULT '5.00' COMMENT '余额下降提醒阈值（元）',
  `usage_saving_threshold` decimal(10,4) DEFAULT '0.5000' COMMENT '节能阈值(度/小时)，低于此值为节能',
  `usage_normal_threshold` decimal(10,4) DEFAULT '1.0000' COMMENT '正常阈值(度/小时)，低于此值为正常，高于为偏高',
  `quiet_hours_start` time DEFAULT '22:00:00' COMMENT '免打扰开始时间',
  `quiet_hours_end` time DEFAULT '08:00:00' COMMENT '免打扰结束时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='电费配置表';

--
-- 转存表中的数据 `nteam_power_config`
--

INSERT INTO `nteam_power_config` (`id`, `power_fee_template_id`, `power_report_template_id`, `price_per_kwh`, `low_balance_threshold`, `critical_balance_threshold`, `arrears_threshold`, `daily_summary_enabled`, `low_balance_enabled`, `critical_balance_enabled`, `arrears_enabled`, `email_push_enabled`, `wechat_push_enabled`, `daily_summary_frequency`, `low_balance_frequency`, `critical_balance_frequency`, `arrears_frequency`, `threshold_amount`, `usage_saving_threshold`, `usage_normal_threshold`, `quiet_hours_start`, `quiet_hours_end`, `created_at`, `updated_at`) VALUES
(1, 4, 5, '0.6500', '30.00', '10.00', '0.00', 1, 1, 1, 1, 1, 1, 'daily', 'daily', 'daily', 'daily', '5.00', '0.5000', '1.0000', '22:00:00', '08:00:00', '2026-05-03 12:14:40', '2026-05-25 11:05:25');

