-- --------------------------------------------------------

--
-- 表的结构 `nteam_push_logs`
--

CREATE TABLE `nteam_push_logs` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `dormitory_binding_id` int(11) NOT NULL COMMENT '宿舍绑定ID',
  `push_type` varchar(20) NOT NULL COMMENT '推送类型：wechat,email',
  `notify_type` varchar(50) NOT NULL COMMENT '通知类型：daily_summary,balance_low,balance_critical,arrears',
  `balance` decimal(10,2) DEFAULT NULL COMMENT '推送时余额',
  `title` varchar(200) DEFAULT NULL COMMENT '推送标题',
  `content` text COMMENT '推送内容',
  `status` tinyint(1) DEFAULT '0' COMMENT '状态：0待发送,1已发送,2发送失败',
  `error_msg` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `sent_at` datetime DEFAULT NULL COMMENT '发送时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='推送记录表';

