--
-- 表的结构 `nteam_push_settings`
--

CREATE TABLE `nteam_push_settings` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `dormitory_binding_id` int(11) NOT NULL COMMENT '宿舍绑定ID',
  `push_types` varchar(100) DEFAULT 'wechat' COMMENT '推送类型：wechat,email,both',
  `notify_types` varchar(255) DEFAULT 'daily_summary,balance_low,balance_critical,arrears' COMMENT '通知类型',
  `balance_low_threshold` decimal(10,2) DEFAULT '30.00' COMMENT '余额不足阈值',
  `balance_critical_threshold` decimal(10,2) DEFAULT '10.00' COMMENT '余额即将耗尽阈值',
  `last_reminder_balance` decimal(10,2) DEFAULT NULL COMMENT '上次提醒时的余额',
  `last_reminder_time` datetime DEFAULT NULL COMMENT '上次提醒时间',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户推送设置表';

--
-- 转存表中的数据 `nteam_push_settings`
--

