--
-- 表的结构 `nteam_subscriptions`
--

CREATE TABLE `nteam_subscriptions` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `openid` varchar(64) NOT NULL COMMENT '微信OpenID',
  `template_id` varchar(64) NOT NULL COMMENT '订阅消息模板ID',
  `subscribe_count` int(11) DEFAULT '0' COMMENT '剩余订阅次数',
  `subscribe_time` datetime DEFAULT NULL COMMENT '订阅时间',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态：1-有效，0-无效',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户订阅消息记录表';

--
-- 转存表中的数据 `nteam_subscriptions`
