--
-- 表的结构 `nteam_tokens`
--

CREATE TABLE `nteam_tokens` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `token_type` varchar(20) NOT NULL COMMENT '令牌类型:email_verify,password_reset',
  `token` varchar(50) NOT NULL COMMENT '令牌值',
  `email` varchar(255) DEFAULT NULL COMMENT '关联邮箱',
  `expire_time` datetime NOT NULL COMMENT '过期时间',
  `used` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已使用:0未使用,1已使用',
  `create_time` datetime NOT NULL COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户令牌表';

