--
-- 表的结构 `nteam_users`
--

CREATE TABLE `nteam_users` (
  `id` int(11) NOT NULL,
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `password` varchar(32) NOT NULL COMMENT '密码(md5)',
  `wx_openid` varchar(64) DEFAULT NULL COMMENT '微信OpenID',
  `wx_bind_time` datetime DEFAULT NULL COMMENT '微信绑定时间',
  `email` varchar(100) NOT NULL COMMENT '邮箱',
  `qq` varchar(20) DEFAULT NULL COMMENT 'QQ号',
  `points` int(11) DEFAULT '0' COMMENT '积分',
  `level` int(11) DEFAULT '1' COMMENT '等级',
  `is_banned` tinyint(1) DEFAULT '0' COMMENT '是否被封禁 0否 1是',
  `email_verified` tinyint(1) DEFAULT '0' COMMENT '邮箱是否已验证 0否 1是',
  `email_verify_code` varchar(32) DEFAULT NULL COMMENT '邮箱验证码',
  `register_time` datetime DEFAULT NULL COMMENT '注册时间',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) DEFAULT NULL COMMENT '最后登录IP',
  `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

